using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var services = new ServiceCollection();
services.AddLogging(builder => builder.AddConsole().SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();
var logger = serviceProvider.GetRequiredService<ILogger<Program>>();

// Create the research tools
var researchTools = new ResearchTools();
var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.TakeNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// Configure the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the SearchWeb tool
        2. Taking notes on key findings using the TakeNote tool
        3. Reviewing your notes with GetNotes when ready to summarize
        4. Providing a comprehensive summary of your findings

        Always search for multiple aspects of the topic, take notes on important points,
        then synthesize your notes into a final summary.
        """,
    Tools = tools,
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
    };

    Console.WriteLine($"\nResearching: {topic}...\n");

    try
    {
        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        logger.LogError(ex, "Agent execution failed");
        Console.WriteLine($"\nError: {ex.Message}");
    }
}

Console.WriteLine("\nGoodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Searches the web for information about a query. Returns relevant search results.")]
    public string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, integrate with a real search API (e.g., Bing Search, Google Custom Search).
        return $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview article covering key concepts and history of {query}.
               Summary: Provides foundational information including definitions, origins, and major developments.

            2. [Research Journal] Recent academic findings related to {query}.
               Summary: Peer-reviewed analysis with data-driven insights and future outlook.

            3. [News Source] Latest developments and current trends in {query}.
               Summary: Up-to-date reporting on recent events, breakthroughs, and industry impact.
            """;
    }

    [Description("Takes a note to remember important research findings. Use this to record key points.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes recorded).";
    }

    [Description("Retrieves all notes taken during this research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return "Research notes:\n" + string.Join("\n", _notes.Select((n, i) => $"  {i + 1}. {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

